  export const paths: path[] = [@first, @second]
}
instance Packed = Paths(first: @First.base, second: @Second.base)
for i in range(min: 0, max: 1, step: 1) carry pick: number = 0 carry edge: path = @Seed carry previous: path = @Seed {
  next edge = @Packed::paths[@pick]
  next previous = @edge
  next pick = @pick + 1
}
const first: number = lineAngle(@previous.start, @Axis.start)
const result: number = lineAngle(@edge.start, @Axis.start)

