line Axis = polar(start: (430, -70), angle: 7, length: 33)
line Seed = polar(start: (-80, -40), angle: 7, length: 33)
module Level0(turn: number, x: number) {
  line Seed = polar(start: (-80, -40), angle: 7, length: 33)
  for i in range(min: 0, max: 1, step: 1) carry edge: path = @Seed {
    arc Generated = arc(center: (@x + @i * 120, 7), radius: 26, start: 287 + @turn + @i * 11, end: 38 + @turn + @i * 11, direction: counterclockwise)
    move Generated as selected (from: (0, 0), to: (17, -9), angleDeg: 13)
    move Generated as later (from: (0, 0), to: (17, -9), angleDeg: 31)
    next edge = @Generated[@i].selected
  }
  export const out: path = @edge
}
module Level1(turn: number, x: number) {
  line Seed = polar(start: (-80, -40), angle: 7, length: 33)
  instance Child = Level0(turn: @turn + 11, x: @x + 130)
  for k in range(min: 0, max: 0, step: 1) carry forwarded: path = @Seed {
    next forwarded = @Child::out
  }
  export const out: path = @forwarded
}
instance Sibling0 = Level1(turn: 0, x: 0)
instance Sibling1 = Level1(turn: 17, x: 370)
instance Sibling2 = Level1(turn: 34, x: 740)
const sibling0: number = lineAngle(@Sibling0::out.end, @Axis.start)
const sibling1: number = lineAngle(@Sibling1::out.end, @Axis.start)
const result: number = lineAngle(@Sibling2::out.end, @Axis.start)

